    if mode == 'floor':
        return numerator // denominator
    if mode == 'half_up':
        return (2 * numerator + denominator) // (2 * denominator)
    raise ValueError('unsupported rounding mode')


def amount(event, mode):
    quantity = event.get('quantity', 1)
    base = event['price'] * quantity
    discount_bp = min(10000, max(0, event.get('discount_bp', 0)))
    net = _round_ratio(base * (10000 - discount_bp), 10000, mode)
    tax_bp = event.get('tax_bp', 0)
    tax = _round_ratio(net * tax_bp, 10000, mode)
    total = net + tax
    if event.get('kind') == 'refund':
        return -total
    return total
